ul { list-style: none; padding-left: 16px }
li.node { padding: 2px 0 }
.status { display: inline-block; width: 52px; font-size: 11px; font-weight: 600; border-radius: 3px; padding: 1px 4px; text-align: center; margin-right: 6px }
.status-open { background: #fff3cd; color: #856404 }
