a { color: #0969da; text-decoration: none }
a:hover { text-decoration: underline }
code { background: #f0f0f0; padding: 1px 4px; border-radius: 3px; font-size: 12px }
.prose { color: #555; font-size: 13px; margin-bottom: 8px }
.depth-limit { color: #999; font-style: italic; font-size: 12px }
.daily-workspace { padding: 16px 24px; max-width: 960px }
.roadmap-frontier { display: flex; flex-direction: column; gap: 20px }
.frontier-bucket { border: 1px solid #e0e0e0; border-radius: 6px; padding: 12px 16px; background: #fff }
.frontier-bucket h2 { font-size: 14px; font-weight: 600; margin: 0 0 8px; text-transform: uppercase; letter-spacing: 0.04em }
.frontier-ready h2 { color: #856404 }
.frontier-upcoming h2 { color: #084298 }
.frontier-done h2 { color: #0a3622 }
.three-gate-progress { display: flex; flex-direction: column; gap: 12px; margin-bottom: 24px }
.three-gate-progress h2 { margin: 0 0 4px }
.gate-row { border: 1px solid #e0e0e0; border-radius: 6px; padding: 12px 16px; background: #fff }
.gate-head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 6px }
.gate-name { font-weight: 600; font-size: 14px }
.gate-count { font-family: ui-monospace, monospace; font-size: 13px; color: #555; font-variant-numeric: tabular-nums }
