const server = require('http').createServer((req, res) => {   const method = req.method || 'GET';
  const rawUrl = req.url || '/';
  const path = rawUrl.split('?')[0] || '/';
  for (const route of routes) if (route.method === method && route.pathRe.test(path)) {   res.writeHead(route.status, { 'Content-Type': route.contentType });
  res.end(route.body);
  return; }
  const pathRoutes = routes.filter((r) => r.pathRe.test(path));
  if (pathRoutes.length > 0) {   const allow = [...new Set(pathRoutes.map((r) => r.method))].join(', ');
  res.writeHead(405, { Allow: allow });
  res.end('Method Not Allowed');
  return; }
  res.writeHead(404);
  res.end('Not Found'); });
const PORT = process.env['PORT'] ? parseInt(process.env['PORT'], 10) : 8080;
const HOST = process.env['HOST'] || '0.0.0.0';
server.listen(PORT, HOST, () => {   process.stdout.write('listening\\n'); });
GUNBC_SERVER_EOF
